  perf.append({'id':r['id'],'input':r['input'],'mode':r['mode'],'new_A_models':r['models'],'HighDiv_models':base['models'],'old_A_models':prev['models'],'new_A_covered':r['covered'],'HighDiv_covered':base['covered'],'old_A_covered':prev['covered'],'total':r['total'],'new_A_percent':r['percentage'],'HighDiv_percent':base['percentage'],'old_A_percent':prev['percentage'],'delta_HighDiv_bits':r['covered']-base['covered'],'delta_HighDiv_pp':r['percentage']-base['percentage'],'delta_old_A_bits':r['covered']-prev['covered'],'new_A_AUC':r['auc_percentage'],'HighDiv_AUC':base['auc_percentage'],'old_A_AUC':prev['auc_percentage'],'complete100':r['complete100'],'time100':r['time100'],'HighDiv_complete100':base['complete100'],'HighDiv_time100':base['time100'],'old_A_complete100':prev['complete100'],'old_A_time100':prev['time100'],'strict_C100_comparable':r['complete100'] and base['complete100'],'first_model':r['first_model'],'status':r['status'],'CDCL_models':r['source_models'].get('CDCL',0),'CCSS_models':r['source_models'].get('CCSS',0),'unknown':sum(v for k,v in r['queries'].items() if k.endswith('_unknown')),'late':r['late']})
  mechanism.append({'id':r['id'],'requests':r['requests'],'registered':r['registered'],'backend_metadata_queries':r['metadata_queries'],'supported_SMT_queries':r['supported_queries'],'max_mappable':r['max_mappable'],'ordinary':n.get('ordinary',0),'within64':r['funnel'].get('within_decision_window',0),'mapped':r['funnel'].get('has_direct_mapping',0),'active':r['funnel'].get('has_current_demand',0),'suggestions':n.get('suggestions',0),'same_phase':n.get('same_phase_suggestions',0),'overrides':n.get('phase_overrides',0),'popped':n.get('popped',0),'native_outside64':r['funnel'].get('outside_decision_window',0),'final_atom_truth_known':final_truth['known'],'final_internal_effective_phase_retained':final_truth['retained'],'final_model_phase_retained':read(ROOT/'results/round2_a/retention_audit_summary.json')[r['id']].get('counts',{}).get('model_phase_retained',0),'metadata_query_fraction':r['metadata_queries']/r['registered'] if r['registered'] else None,'supported_query_fraction':r['supported_queries']/r['registered'] if r['registered'] else None,'direct_mapping_rate':r['funnel'].get('has_direct_mapping',0)/r['funnel']['within_decision_window'] if r['funnel'].get('within_decision_window') else None,'active_demand_rate':r['funnel'].get('has_current_demand',0)/r['funnel']['has_direct_mapping'] if r['funnel'].get('has_direct_mapping') else None,'outside64_potential':'NA','unmapped':r['funnel'].get('unmapped_reason_unknown',0),'quota_rejected':r['funnel'].get('quota_rejected',0),'no_active_demand':r['funnel'].get('no_active_demand',0),'backend':json.dumps(r['backend'],ensure_ascii=False)})
